  static const int WIFI_REASON_GROUP_CIPHER_NOT_VALID = 18;

  /// Invalid pairwise cipher
  static const int WIFI_REASON_PAIRWISE_CIPHER_NOT_VALID = 19;

  /// Invalid AKMP
  static const int WIFI_REASON_AKMP_NOT_VALID = 20;

  /// Unsupported RSNE version
  static const int WIFI_REASON_UNSUPPORTED_RSN_IE_VERSION = 21;

  /// Invalid RSNE capabilities
  static const int WIFI_REASON_INVALID_RSN_IE_CAPAB = 22;

  /// IEEE 802.1X authentication failed
  static const int WIFI_REASON_IEEE_802_1X_AUTH_FAILED = 23;

  /// Cipher suite rejected because of the security policy
  static const int WIFI_REASON_CIPHER_SUITE_REJECTED = 24;

  /// TDLS direct-link teardown due to TDLS peer STA unreachable via the
  /// TDLS direct link
  static const int WIFI_REASON_TDLS_TEARDOWN_UNREACHABLE = 25;

  /// TDLS direct-link teardown for unspecified reason
  static const int WIFI_REASON_TDLS_TEARDOWN_UNSPECIFIED = 26;

  /// Disassociated because excessive number of frames need to be acknowledged,
